import assert from 'node:assert/strict';import {mkdtemp,writeFile,readFile,readdir,rm,copyFile} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {saveExportBundle} from '../export-bundle.mjs';import Q from '../speech-quality-core.js';
const tmp=await mkdtemp(join(tmpdir(),'bundle-recovery-'));try{const source=join(tmp,'source.mp4'),srt=join(tmp,'source.srt'),vtt=join(tmp,'source.vtt'),directory=join(tmp,'Videos');await writeFile(source,'owned synthetic movie');await writeFile(srt,'observed synthetic words');await writeFile(vtt,'WEBVTT');const args={directory,source,stem:'Movie',sidecars:[{extension:'srt',path:srt},{extension:'vtt',path:vtt}]};let copies=0;await assert.rejects(saveExportBundle({...args,copyImpl:async(...a)=>{if(++copies===2)throw Error('Injected sidecar failure');return copyFile(...a);}}),/Injected/);assert.deepEqual(await readdir(directory),['Movie.mp4']);let movieCopies=0;const result=await saveExportBundle({...args,copyImpl:async(...a)=>{if(a[0]===source)movieCopies++;return copyFile(...a);}});assert.equal(movieCopies,0);assert.equal(result.stem,'Movie');assert.deepEqual((await readdir(directory)).sort(),['Movie.mp4','Movie.srt','Movie.vtt']);assert.equal((await saveExportBundle(args)).existing,true);await writeFile(join(directory,'Movie.srt'),'unrelated sidecar');const collision=await saveExportBundle(args);assert.equal(collision.stem,'Movie (1)');assert.equal(await readFile(join(directory,'Movie.srt'),'utf8'),'unrelated sidecar');let unblock,entered;const hold=new Promise(r=>unblock=r),started=new Promise(r=>entered=r);let movies=0;const parallel={...args,stem:'Concurrent'};const first=saveExportBundle({...parallel,copyImpl:async(...a)=>{await copyFile(...a);if(a[0]===source){movies++;entered();await hold;}}});await started;const second=saveExportBundle({...parallel,copyImpl:async(...a)=>{if(a[0]===source)movies++;return copyFile(...a);}});unblock();const both=await Promise.all([first,second]);assert.equal(movies,1);assert.equal(both[0].stem,both[1].stem);assert.equal(both[1].existing,true);const word=String.raw`literal {\an8} back\slash &amp; <i>entities</i>`;for(const format of ['srt','vtt']){const text=Q.subtitles([{start:0,end:1,word}],2,format);assert(text.includes(String.raw`{\an8} back\slash`));assert(text.includes('&amp;amp; &lt;i&gt;entities&lt;/i&gt;'));assert(!text.includes('<i>'));}console.log('PASS sidecar failure after MP4 copy recovers one matching bundle without recopy; conflicting bytes preserved; observed braces/backslashes/entities escaped as literal subtitles.');}finally{await rm(tmp,{recursive:true,force:true});}
